<div class="ranking-podium"><?php foreach($r['podium'] as $winner): ?><a href="/profili/?Id=<?=$winner['id']?>" class="ranking-winner ranking-place-<?=$winner['position']?>"><img class="ranking-crown" src="/assets/placeholder.svg" width="100" height="74" alt="<?=$winner['position']?>º posto"><img class="ranking-portrait" src="<?=$h($winner['portrait'])?>" data-default-src="<?=$h($winner['fallback'])?>" data-privacy-compact width="88" height="88" alt=""><span class="ranking-place-label"><?=$winner['position']?>º classificato</span><strong><?=$h($winner['name'])?></strong><span class="ranking-score"><?=$fmt($winner['value'])?> <small><?=$h($r['definition']['unit'])?></small></span></a><?php endforeach; ?><?php if(!$r['podium']): ?><p>Nessun personaggio presente in classifica.</p><?php endif; ?></div>
