<section class="ranking-results" aria-labelledby="ranking-results-title"><div class="ranking-section-heading"><h2 id="ranking-results-title">Il registro · <?=$h($r['definition']['label'])?></h2><?php if($r['own']): ?><a class="ranking-own" href="<?=$h($link($r['metric'],(int)ceil($r['own']['position']/20)))?>#ranking-player-<?=$r['own']['id']?>">La tua posizione <strong>#<?=$r['own']['position']?></strong> · <?=$fmt($r['own']['value'])?> <?=$h($r['definition']['unit'])?></a><?php endif; ?></div>
<ol class="ranking-list" start="<?=($r['page']-1)*20+1?>"><?php foreach($r['players'] as $player): ?><li id="ranking-player-<?=$player['id']?>" class="ranking-row<?=$r['own']&&$player['id']===$r['own']['id']?' is-own':''?>"><span class="ranking-position">#<?=$player['position']?></span><a class="ranking-person" href="/profili/?Id=<?=$player['id']?>"><img src="<?=$h($player['portrait'])?>" data-default-src="<?=$h($player['fallback'])?>" data-privacy-compact width="48" height="48" loading="lazy" alt=""><span><strong><?=$h($player['name'])?></strong></span></a><strong class="ranking-value"><?=$fmt($player['value'])?><small><?=$h($r['definition']['unit'])?></small></strong></li><?php endforeach; ?></ol>
